/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: project, slugs, memoryStore
 *   Constants: catalog
 * Tests
 *   - the catalog has unique slugs and includes every portfolio project
 *   - resolving storage keeps the stored order, drops unknown slugs, and appends new catalog projects
 *   - changes move within bounds and report no-ops
 *   - administrator changes check the revision and persist the full order
 *   - a write lost to a concurrent administrator reports stale
 *   - the public list hides hidden projects and falls back to defaults when storage fails
 *   - the homepage lists only the given projects and escapes their copy
 *   - the bento grid features the first project and pairs the rest
 *   - the console renders every project with its revision and disables moves at the ends
 *   - the console authenticates and authorizes before any route handler
 *   - login may return to the projects console
 *   - signed-out visitors are sent to login and never reach the store
 * @end-catalog */

import assert from 'node:assert/strict';
import { Server } from 'node:http';
import os from 'node:os';
import path from 'node:path';
import test from 'node:test';

import { createApp } from '../../src/app';
import { safeWebReturnTo } from '../../src/controllers/authController';
import {
    applyPortfolioChange,
    changePortfolio,
    listPublicPortfolioProjects,
    resolvePortfolio,
    type PortfolioStore,
    type StoredPortfolio,
    type StoredPortfolioEntry
} from '../../src/portfolio/portfolioStore';
import { portfolioProjects, type PortfolioProject } from '../../src/portfolio/projectCatalog';
import { createPortfolioAdminRouter } from '../../src/routes/portfolioAdminRoutes';
import { renderPortfolioAdminPage } from '../../src/views/portfolio/adminProjectsView';
import { portfolioTileSlots, renderHomePage } from '../../src/views/portfolio/homeView';

const project = (slug: string, overrides: Partial<PortfolioProject> = {}): PortfolioProject => ({
    slug,
    name: slug.toUpperCase(),
    tagline: `${slug} tagline`,
    description: `${slug} description`,
    tags: ['Web'],
    icon: 'cube',
    link: { label: `Open ${slug}`, href: `/${slug}` },
    accent: 'blue',
    preview: 'player',
    defaultVisibility: 'public',
    ...overrides
});
const catalog = [project('a'), project('b'), project('c', { defaultVisibility: 'hidden' })];
const slugs = (entries: { project: PortfolioProject }[]) => entries.map((entry) => entry.project.slug);

/** In-memory store with the same revision semantics as the MongoDB store. */
const memoryStore = (initial: StoredPortfolio | null = null) => {
    let stored = initial;
    const writes: { expectedRevision: number; projects: StoredPortfolioEntry[]; actorId: string }[] = [];
    const store: PortfolioStore & { writes: typeof writes; current: () => StoredPortfolio | null } = {
        writes,
        current: () => stored,
        async read() { return stored; },
        async write(expectedRevision, projects, actorId) {
            writes.push({ expectedRevision, projects, actorId });
            if ((stored?.revision ?? 0) !== expectedRevision) return false;
            stored = { revision: expectedRevision + 1, projects };
            return true;
        }
    };
    return store;
};

test('the catalog has unique slugs and includes every portfolio project', () => {
    const catalogSlugs = portfolioProjects.map((entry) => entry.slug);
    assert.equal(new Set(catalogSlugs).size, catalogSlugs.length);
    for (const slug of ['finitude', 'finitude-ios', 'finitude-android', 'naruto-mobile', 'ootd']) {
        assert.ok(catalogSlugs.includes(slug), slug);
    }
    assert.equal(portfolioProjects.find((entry) => entry.slug === 'ootd')?.defaultVisibility, 'hidden');
});

test('resolving storage keeps the stored order, drops unknown slugs, and appends new catalog projects', () => {
    assert.deepEqual(resolvePortfolio(null, catalog).entries.map((entry) => [entry.project.slug, entry.visibility]), [
        ['a', 'public'], ['b', 'public'], ['c', 'hidden']
    ]);
    const resolved = resolvePortfolio({
        revision: 4,
        projects: [
            { slug: 'b', visibility: 'hidden' },
            { slug: 'retired', visibility: 'public' },
            { slug: 'b', visibility: 'public' },
            { slug: 'c', visibility: 'public' }
        ]
    }, catalog);
    assert.equal(resolved.revision, 4);
    assert.deepEqual(resolved.entries.map((entry) => [entry.project.slug, entry.visibility]), [
        ['b', 'hidden'], ['c', 'public'], ['a', 'public']
    ]);
});

test('changes move within bounds and report no-ops', () => {
    const entries = resolvePortfolio(null, catalog).entries;
    assert.deepEqual(slugs(applyPortfolioChange(entries, { kind: 'move', slug: 'b', direction: 'up' })!), ['b', 'a', 'c']);
    assert.deepEqual(slugs(applyPortfolioChange(entries, { kind: 'move', slug: 'b', direction: 'down' })!), ['a', 'c', 'b']);
    assert.equal(applyPortfolioChange(entries, { kind: 'move', slug: 'a', direction: 'up' }), null);
    assert.equal(applyPortfolioChange(entries, { kind: 'move', slug: 'c', direction: 'down' }), null);
    assert.equal(applyPortfolioChange(entries, { kind: 'visibility', slug: 'a', visibility: 'public' }), null);
    assert.equal(applyPortfolioChange(entries, { kind: 'visibility', slug: 'a', visibility: 'hidden' })![0].visibility, 'hidden');
    assert.equal(applyPortfolioChange(entries, { kind: 'move', slug: 'missing', direction: 'up' }), null);
});

test('administrator changes check the revision and persist the full order', async () => {
    const store = memoryStore();
    assert.equal(await changePortfolio(store, 0, { kind: 'move', slug: 'c', direction: 'up' }, 'admin-1', catalog), 'applied');
    assert.deepEqual(store.current(), {
        revision: 1,
        projects: [{ slug: 'a', visibility: 'public' }, { slug: 'c', visibility: 'hidden' }, { slug: 'b', visibility: 'public' }]
    });
    assert.equal(store.writes[0].actorId, 'admin-1');

    // A page rendered before that change carries revision 0 and must not overwrite it.
    assert.equal(await changePortfolio(store, 0, { kind: 'visibility', slug: 'c', visibility: 'public' }, 'admin-2', catalog), 'stale');
    assert.equal(await changePortfolio(store, 1, { kind: 'visibility', slug: 'c', visibility: 'public' }, 'admin-2', catalog), 'applied');
    assert.equal(await changePortfolio(store, 2, { kind: 'move', slug: 'a', direction: 'up' }, 'admin-2', catalog), 'noop');
    assert.equal(await changePortfolio(store, 2, { kind: 'move', slug: 'retired', direction: 'up' }, 'admin-2', catalog), 'unknown_project');
    assert.equal(store.writes.length, 2);
});

test('a write lost to a concurrent administrator reports stale', async () => {
    const store = memoryStore();
    const racing: PortfolioStore = { read: store.read, write: async () => false };
    assert.equal(await changePortfolio(racing, 0, { kind: 'visibility', slug: 'a', visibility: 'hidden' }, 'admin', catalog), 'stale');
});

test('the public list hides hidden projects and falls back to defaults when storage fails', async () => {
    const store = memoryStore({ revision: 3, projects: [{ slug: 'ootd', visibility: 'public' }, { slug: 'finitude', visibility: 'hidden' }] });
    const visible = (await listPublicPortfolioProjects(store)).map((entry) => entry.slug);
    assert.equal(visible[0], 'ootd');
    assert.ok(!visible.includes('finitude'));

    const failures: unknown[] = [];
    const broken: PortfolioStore = { read: async () => { throw new Error('offline'); }, write: async () => false };
    const fallback = (await listPublicPortfolioProjects(broken, (error) => failures.push(error))).map((entry) => entry.slug);
    assert.deepEqual(fallback, portfolioProjects.filter((entry) => entry.defaultVisibility === 'public').map((entry) => entry.slug));
    assert.equal(failures.length, 1);
});

test('the homepage lists only the given projects and escapes their copy', () => {
    const html = renderHomePage({
        projects: [project('a', { name: 'A <script>', link: null }), project('b')],
        year: 2026
    });
    assert.match(html, /A &lt;script&gt;/);
    assert.doesNotMatch(html, /A <script>/);
    assert.match(html, /No public link yet/);
    assert.match(html, /href="\/b">Open b/);
    assert.match(html, /2 projects/);
    assert.match(html, /© 2026/);
    assert.match(renderHomePage({ projects: [] }), /No projects are public right now/);
});

test('the bento grid features the first project and pairs the rest', () => {
    assert.deepEqual(portfolioTileSlots(0), []);
    assert.deepEqual(portfolioTileSlots(1), ['wide']);
    assert.deepEqual(portfolioTileSlots(2), ['feature', 'side-tall']);
    assert.deepEqual(portfolioTileSlots(3), ['feature', 'side', 'side']);
    assert.deepEqual(portfolioTileSlots(4), ['feature', 'side', 'side', 'wide']);
    assert.deepEqual(portfolioTileSlots(5), ['feature', 'side', 'side', 'half', 'half']);
    assert.deepEqual(portfolioTileSlots(6), ['feature', 'side', 'side', 'half', 'half', 'wide']);

    const html = renderHomePage({ projects: [project('a'), project('b', { accent: 'orange', preview: 'comments' })], year: 2026 });
    assert.match(html, /class="tile tile--feature tile--blue"/);
    assert.match(html, /class="tile tile--side-tall tile--orange"/);
    assert.match(html, /class="art art--comments" aria-hidden="true"/);
    assert.match(html, /class="pf-button pf-button--accent tile__link" href="\/a">Open a/);
    assert.doesNotMatch(html, /style=/);
});

test('the console renders every project with its revision and disables moves at the ends', () => {
    const html = renderPortfolioAdminPage({
        adminEmail: 'admin+<x>@example.com',
        portfolio: resolvePortfolio({ revision: 7, projects: [] }, catalog),
        notice: 'stale'
    });
    assert.match(html, /admin\+&lt;x&gt;@example\.com/);
    assert.equal(html.match(/name="revision" value="7"/g)?.length, catalog.length * 3);
    assert.match(html, /disabled aria-label="Move A up"/);
    assert.match(html, /disabled aria-label="Move C down"/);
    assert.match(html, /action="\/admin\/projects\/c\/visibility"[\s\S]*?name="visibility" value="public"/);
    assert.match(html, /2 of 3 public/);
    assert.match(html, /class="alert alert--error"/);
});

test('the console authenticates and authorizes before any route handler', () => {
    const stack = (createPortfolioAdminRouter({ store: memoryStore() }) as unknown as { stack: { name: string; route?: unknown }[] }).stack;
    const firstRoute = stack.findIndex((layer) => Boolean(layer.route));
    assert.deepEqual(stack.slice(0, 2).map((layer) => layer.name), ['requireAuthForWeb', 'requireAdminForWeb']);
    assert.ok(firstRoute > 2);
});

test('login may return to the projects console', () => {
    assert.equal(safeWebReturnTo('/admin/projects'), '/admin/projects');
    assert.equal(safeWebReturnTo('/admin/projects/ootd/move'), '/');
    assert.equal(safeWebReturnTo('/admin/social/reports'), '/');
});

test('signed-out visitors are sent to login and never reach the store', async () => {
    const store = memoryStore();
    let reads = 0;
    const counting: PortfolioStore = { read: async () => { reads += 1; return store.read(); }, write: store.write };
    const app = createApp({
        environment: 'test',
        listenerDistPath: path.join(os.tmpdir(), 'archtree-portfolio-listener-missing'),
        portfolioStore: counting
    });
    const server = await new Promise<Server>((resolve) => {
        const listening = app.listen(0, '127.0.0.1', () => resolve(listening));
    });
    const address = server.address();
    assert.ok(address && typeof address !== 'string');
    const base = `http://127.0.0.1:${address.port}`;
    try {
        const page = await fetch(`${base}/admin/projects`, { redirect: 'manual' });
        assert.equal(page.status, 302);
        assert.equal(page.headers.get('location'), '/auth/login-web?returnTo=%2Fadmin%2Fprojects');

        const mutation = await fetch(`${base}/admin/projects/ootd/visibility`, {
            method: 'POST',
            redirect: 'manual',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: 'revision=0&visibility=public'
        });
        assert.equal(mutation.status, 302);
        assert.match(mutation.headers.get('location') ?? '', /^\/auth\/login-web/);
        assert.equal(reads, 0);
        assert.equal(store.writes.length, 0);

        const home = await fetch(`${base}/`);
        assert.equal(home.status, 200);
        assert.equal(reads, 1);
    } finally {
        await new Promise<void>((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
    }
});
